import os, subprocess, sys
runner = "@stub.runner@"
workDir = "@stub.workDir@"
skipErrors = "@stub.skipErrors@"
svcRoot = "@stub.serviceAsRoot@"
print(f"Stopping service {runner}")
try:
    if not svcRoot:
        subprocess.run(["systemctl", "--user", "stop", f"{runner}.service"], check=True)
    else:
        subprocess.run(["systemctl", "stop", f"{runner}.service"], check=True)
except subprocess.CalledProcessError as e:
