    if skipErrors == "false": sys.exit(1)

import os, subprocess, requests, shutil, json
TOKEN = "@stub.rdToken@"
SVCROOT = "@stub.serviceAsRoot@"
PROJECT = "@stub.project@"
RDURL = "@stub.rdUrl@"
RUNNER = "@stub.runner@"
WORKDIR = "@stub.workDir@"
ARCH = "@stub.architecture@"
RUNNERTYPE = "@stub.runnerType@"

requests.packages.urllib3.disable_warnings()
session = requests.Session(); session.verify = False
headers = {"X-Rundeck-Auth-Token": TOKEN, "Accept": "application/json"}
api_base = f"{RDURL}/project/{PROJECT}/runnerManagement"

print(f"Uninstalling {RUNNER} on {WORKDIR}")
try:
    if not SVCROOT:
        subprocess.run(["systemctl", "--user", "disable", "--now", f"{RUNNER}.service"], check=False)
        subprocess.run(["systemctl", "--user", "daemon-reload"], check=False)
    else:
        subprocess.run(["systemctl", "disable", "--now", f"{RUNNER}.service"], check=False)
        subprocess.run(["systemctl", "daemon-reload"], check=False)
except Exception as e:
    print(f"Warning: Error stopping systemd service: {e}")

if RUNNERTYPE == "rba-runner":
    if ARCH == "replica":
        try:
            with open(f"{WORKDIR}/.replica-meta", "r") as f:
                meta = json.load(f)
            print(f"Deregistering Replica {meta['replicaId']}...")
            session.delete(f"{api_base}/runner/{meta['runnerId']}/replica/{meta['replicaId']}", headers=headers)
        except Exception as e:
            print(f"Warning: Could not deregister replica: {e}")
    else:
        response = session.get(f"{api_base}/runners", headers=headers)
        if response.status_code == 200:
            runners = response.json().get("runners", [])
            runner_info = next((r for r in runners if r["name"] == RUNNER), None)
            if runner_info:
                runner_id = runner_info.get("id")
                session.delete(f"{api_base}/runner/{runner_id}", headers=headers)

try:
    if not SVCROOT:
        service_file = os.path.join(os.getenv("HOME"), ".config", "systemd", "user", f"{RUNNER}.service")
    else:
        service_file = f"/etc/systemd/system/{RUNNER}.service"
    if os.path.exists(service_file): os.remove(service_file)
except: pass

if os.path.exists(WORKDIR):
    shutil.rmtree(WORKDIR)
    print(f"Successfully removed {WORKDIR}.")

import os, subprocess
RUNNER = "@stub.runner@"
WORKDIR = "@stub.workDir@"
SVCROOT = "@stub.serviceAsRoot@"

os.chdir(WORKDIR)
print(f"Starting service {RUNNER}")
try:
    if not SVCROOT:
        subprocess.run(["systemctl", "--user", "start", f"{RUNNER}.service"], check=True)
    else:
        subprocess.run(["systemctl", "start", f"{RUNNER}.service"], check=True)
except subprocess.CalledProcessError as e:
    print(f"Error: {e}"); exit(1)

import os, subprocess, json, requests
TOKEN = "@stub.rdToken@"
PROJECT = "@stub.project@"
RDURL = "@stub.rdUrl@"
RUNNER = "@stub.runner@"
WORKDIR = "@stub.workDir@"
ARCH = "@stub.architecture@"
RUNNERTYPE = "@stub.runnerType@"

requests.packages.urllib3.disable_warnings()
headers = {"X-Rundeck-Auth-Token": TOKEN, "Accept": "application/json"}
api_base = f"{RDURL}/project/{PROJECT}/runnerManagement"

try:
    os.chdir(WORKDIR)
    with open(f"{RUNNER}.pid", 'r') as pid_file:
        pid = pid_file.read().strip()
        subprocess.run(["ps", "-fp", pid], check=False)
except Exception as e:
    print(e)

if RUNNERTYPE == "rba-runner":
    print(f"\nChecking status on {RDURL}")
    if ARCH == "replica":
        try:
            with open(f"{WORKDIR}/.replica-meta", "r") as f:
                meta = json.load(f)
            res = requests.get(f"{api_base}/runner/{meta['runnerId']}/replicas", headers=headers, verify=False)
            if res.status_code == 200:
                health = next((r for r in res.json().get('replicas', []) if r['replicaId'] == meta['replicaId']), None)
                if health:
                    print(json.dumps(health, indent=2))
                    if health.get('lastCheckinAlert'): print("\n⚠️ ALERT: Missed last check-in!")
                    if health.get('versionWarning'): print("\n⚠️ WARNING: Outdated version. Please Upgrade.")
                else:
                    print("Replica NOT registered on the server.")
        except:
            print("No replica metadata found locally.")
    else:
        response = requests.get(f"{api_base}/runners", headers=headers, verify=False)
        if response.status_code == 200:
            runners = response.json().get('runners', [])
            runner_info = next((r for r in runners if r['name'] == RUNNER), None)
            if runner_info:
                RUNNERID = runner_info.get('id')
                response = requests.get(f"{RDURL}/runnerManagement/runner/{RUNNERID}", headers=headers, verify=False)
                print(json.dumps(response.json(), indent=4) if response.status_code == 200 else f"Failed to retrieve detailed status for {RUNNER}")
            else:
                print(f"Runner {RUNNER} not found on server")
else:
    print("\nPagerDuty Runner detected. Skipping RBA API status check.")

